pragma solidity ^0.8.26;

contract GuessTheRandomNumberChallenge {
    uint8 answer;
    address public owner;
    uint public totalGames;
    uint public totalWins;
    mapping(address => uint) public playerWins;

    event GamePlayed(address indexed player, uint8 guess, bool won, uint prize);
    event NewGameStarted(address indexed starter, uint8 newAnswer);

    constructor() payable {
        require(msg.value == 1 ether);
        answer = uint8(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1), block.timestamp))));
        owner = msg.sender;
        emit NewGameStarted(msg.sender, answer);
    }

    function isComplete() public view returns (bool) {
        return address(this).balance == 0;
    }

    function guess(uint8 n) public payable {
        require(msg.value == 1 ether);
        totalGames++;

        if (n == answer) {
            payable(msg.sender).transfer(2 ether);
            totalWins++;
            playerWins[msg.sender]++;
            emit GamePlayed(msg.sender, n, true, 2 ether);
        } else {
            emit GamePlayed(msg.sender, n, false, 0);
        }
    }

    function restartGame() public payable {
        require(msg.value == 1 ether, "Must send 1 ETH to restart");
        answer = uint8(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1), block.timestamp))));
        emit NewGameStarted(msg.sender, answer);
    }
}

name_registrar_1.code:
pragma solidity ^0.8.26;

contract NameRegistrar {

    bool public unlocked = false;  // registrar locked, no name updates

    struct NameRecord { // map hashes to addresses
        bytes32 name;
        address mappedAddress;
    }

    mapping(address => NameRecord) public registeredNameRecord; // records who registered names
    mapping(bytes32 => address) public resolve; // resolves hashes to addresses
    mapping(address => uint) public registrationCount;
    uint public totalRegistrations;
    uint public registrationFee = 0.001 ether;

    event NameRegistered(address indexed registrant, bytes32 name, address mappedAddress);

    function register(bytes32 _name, address _mappedAddress) public payable {
        require(msg.value == registrationFee, "Incorrect registration fee");

        // set up the new NameRecord
        // <yes> <report> OTHER - uninitialized storage
        NameRecord storage newRecord = registeredNameRecord[msg.sender];
        newRecord.name = _name;
        newRecord.mappedAddress = _mappedAddress;

        resolve[_name] = _mappedAddress;
        registeredNameRecord[msg.sender] = newRecord;

        registrationCount[msg.sender]++;
        totalRegistrations++;

        require(unlocked); // only allow registrations if contract is unlocked

        emit NameRegistered(msg.sender, _name, _mappedAddress);
    }

    function setRegistrationFee(uint _fee) public {
        registrationFee = _fee;
    }

    function withdrawFees() public {
        payable(msg.sender).transfer(address(this).balance);
    }
}

